// Launch Params: the launch row is the whole contract of Enrich Phones. Two ways to fill it:
//   a view      Client (resolves the base), View (a People view by name), Tag (log only). Table is
//               implied People, read defensively and refused only when it names something else.
//   contacts    Contact holds one or more Hub Contacts rows: the run works exactly those people on
//               the Hub and ignores View. Client is optional there (attached to the log when set).
// Nothing else is read: FullEnrich is the one provider and that is code, not a launch parameter.
//
// REFUSALS. A badly filled launch row is an expected outcome, not a crash, and it must be visible on
// the row the Operator launched: every guard RETURNS a refusal item (`refused` carries the reason),
// Launch OK? routes it to Build Refusal, which closes the row as Failed with the reason. FullEnrich
// is not called, so a bad row never costs a credit.
const HUB='appQG6dK0FIOhTxOl', HUB_CONTACTS='tblzexq9qzO9IRiYV';
const rec=$('Fetch Launch Record').first().json||{};
const f=rec.fields||{};
const cf=(($('Resolve Base').first().json||{}).fields)||{};
const arr=(v)=>Array.isArray(v)?v:(v==null||v===''?[]:[v]);
const idOf=(x)=>String((x&&typeof x==='object')?(x.id||''):(x||'')).trim();
const clientRecId=arr(f['Client']).map(idOf).filter(Boolean)[0]||'';
const contactIds=Array.from(new Set(arr(f['Contact']).map(idOf).filter(x=>/^rec[A-Za-z0-9]{14}$/.test(x))));
const table=((f['Table']||'')+'').trim();
const view=((f['View']||'')+'').trim();
const tag=((f['Tag']||'')+'').trim();
const startedAt=new Date().toISOString();
const where='Launch record '+(rec.id||'?');
const ctx={ mode:'view', base:'', tableId:'', clientRecId, table:'People', view, tag, contactIds:[], contactFormula:'', trigger:'form', _launchRecordId:rec.id||'', startedAt };
const refuse=(reason)=>[{ json:Object.assign({}, ctx, { refused:reason }) }];
if(contactIds.length){
  const formula='OR('+contactIds.map(id=>"RECORD_ID()='"+id+"'").join(',')+')';
  return [{ json:Object.assign({}, ctx, { refused:'', mode:'contacts', base:HUB, tableId:HUB_CONTACTS, table:'Contacts', view:'', contactIds, contactFormula:formula }) }];
}
const base=((cf['Clayroots Base ID']||'')+'').trim();
ctx.base=base;
if(!clientRecId){ return refuse(where+' has no Client link and no Contact. Give it a Client and a People View, or one or more Contacts. FullEnrich was not called.'); }
if(!/^app[A-Za-z0-9]{14}$/.test(base)){ return refuse('Client on '+where.toLowerCase()+' has no valid Clayroots Base ID. FullEnrich was not called.'); }
if(table&&table.toLowerCase()!=='people'){ return refuse(where+' names Table "'+table+'". Enrich Phones runs on People, which is implied; leave Table empty. FullEnrich was not called.'); }
if(!view){ return refuse(where+' has no View and no Contact. A People view is required by name, and it is the spend cap: only the people in it are looked up. FullEnrich was not called.'); }
return [{ json:Object.assign({}, ctx, { refused:'' }) }];

// Build Refusal: the row a refused run writes. Two guards reach here and neither throws: the entry
// (a badly filled launch row or event body) and Check Columns (People is missing a field this
// Rootflow needs and does not own). The row is closed as Failed with the reason, on the launch row
// itself when there was one (Stamp Running already put this Execution ID on it) and as its own Hub
// row otherwise. Nothing ran and no FullEnrich credit was spent.
let p={}; try{ p=$('Params').first().json||{}; }catch(e){}
let reason=String(p.refused||'');
let missing='';
if(!reason){ try{ const c=$('Check Columns').first().json||{}; reason=String(c.refused||''); missing=(c.missing||[]).join(', '); }catch(e){} }
if(!reason) reason='the run was refused and no reason was recorded';
const show=(v)=>(v===''||v===null||v===undefined)?'(empty)':String(v);
const lines=[
  '**Refused before anything ran: '+reason+'**',
  '',
  '**The launch as this Rootflow read it**',
  '- **Client:** '+show(p.clientRecId),
  '- **Clayroots Base ID:** '+(p.mode==='contacts'?'(not used: the run was on Hub contacts)':(p.base||'(empty, or the Clients row could not be read)')),
  '- **Table:** People (implied)',
  '- **View:** '+show(p.view),
  '- **Contact:** '+(((p.contactIds||[]).length)?p.contactIds.join(', '):'(empty)'),
  '- **Tag:** '+show(p.tag)
];
if(missing) lines.push('', '**Missing fields:** '+missing+'. Enrich Phones creates only its own phone lane; the core belongs to the scaffold and to Enrich Contacts.');
lines.push(
  '',
  '**Failures (1)**',
  '- Guard: '+reason,
  '',
  'FullEnrich was not called, no credit was spent and nothing was written.',
  'Fix the named thing, clear Execution ID and Status on the launch row, and the launch automation fires it again.'
);
let dur=0; try{ dur=Math.max(0,Math.round(($now.toMillis()-new Date(p.startedAt).getTime())/1000)); }catch(e){}
const log={ 'Automation':'Enrich Phones', 'Status':'Failed', 'Trigger':p.trigger||'form', 'Errors':1, 'Run at':$now.toISO(), 'Records In':0, 'Records Out':0, 'Duration s':dur, 'Description':lines.join('\n'), 'Execution Link':'https://n8n.flowroots.com/workflow/'+$workflow.id+'/executions/'+$execution.id, 'Execution ID':String($execution.id) };
if(p.view) log['View']=p.view;
if(p.clientRecId) log['Client']=[p.clientRecId];
return [{ json: log }];

// Event Params: the record door of Enrich Phones, for a caller that holds no launch row. Two bodies:
//   {baseId, clientRecordId, view}       a People view of a client base (same shape as Enrich Emails)
//   {contactIds:[...], clientRecordId?}  one or more Hub Contacts rows
// The door answers 200 on receipt and the run carries on alone, so a caller never waits on a phone
// lookup. A bad body is a refusal on the run's own Hub row, never a crash.
const HUB='appQG6dK0FIOhTxOl', HUB_CONTACTS='tblzexq9qzO9IRiYV';
const b=($input.first().json||{}).body||{};
const s=(v)=>String(v==null?'':v).trim();
const clientRecId=s(b.clientRecordId||b.clientRecId);
const ctx={ mode:'view', base:'', tableId:'', clientRecId, table:'People', view:s(b.view), tag:s(b.tag), contactIds:[], contactFormula:'', trigger:'event', _launchRecordId:'', startedAt:new Date().toISOString() };
const refuse=(reason)=>[{ json:Object.assign({}, ctx, { refused:reason }) }];
const ids=Array.from(new Set((Array.isArray(b.contactIds)?b.contactIds:[]).map(s).filter(x=>/^rec[A-Za-z0-9]{14}$/.test(x))));
if(ids.length){
  const formula='OR('+ids.map(id=>"RECORD_ID()='"+id+"'").join(',')+')';
  return [{ json:Object.assign({}, ctx, { refused:'', mode:'contacts', base:HUB, tableId:HUB_CONTACTS, table:'Contacts', view:'', contactIds:ids, contactFormula:formula }) }];
}
const base=s(b.baseId||b.base);
const table=s(b.table||'People');
ctx.base=base;
if(!/^app[A-Za-z0-9]{14}$/.test(base)) return refuse('Enrich Phones record door: no valid baseId and no contactIds in the body. FullEnrich was not called.');
if(table.toLowerCase()!=='people') return refuse('Enrich Phones record door: Table "'+table+'" is not People. FullEnrich was not called.');
if(!ctx.view) return refuse('Enrich Phones record door: no view in the body. A People view is the spend cap. FullEnrich was not called.');
return [{ json:Object.assign({}, ctx, { refused:'' }) }];

// Params: one shape for both entries. Whichever entry ran wrote its item (a refusal included); this
// re-emits it so every node after reads $('Params') and never cares which door opened the run.
let p=null;
try{ p=$('Launch Params').first().json; }catch(e){}
if(!p||!p.startedAt){ try{ p=$('Event Params').first().json; }catch(e){} }
if(!p||!p.startedAt) throw new Error('Enrich Phones: no entry produced launch parameters.');
return [{ json:p }];

// Resolve Table: People by name in the base meta just read, the view by name or id (both required,
// no defaults). Field names and types travel for the requirements check. Nothing here creates.
const p=$('Params').first().json;
const r=$input.first().json||{}; const body=(r.body!==undefined)?r.body:r;
const tables=(body&&Array.isArray(body.tables))?body.tables:null;
if(!tables) throw new Error('Could not read the table list for base '+p.base+': '+JSON.stringify(body).slice(0,200)+'. No provider was called.');
const t=tables.find(x=>String(x.name||'').trim().toLowerCase()==='people');
if(!t) throw new Error('Base '+p.base+' has no People table. No provider was called.');
const v=(t.views||[]).find(x=>x.id===p.view||String(x.name||'').trim()===p.view);
if(!v) throw new Error('People ('+t.id+') in base '+p.base+' has no view "'+p.view+'". No provider was called.');
const types={}; for(const f of (t.fields||[])) types[f.name]=f.type;
return [{ json:{ tableId:t.id, tableName:t.name, viewId:v.id, viewName:v.name, fieldNames:(t.fields||[]).map(f=>f.name), fieldTypes:types } }];

// Check Columns: the Rootflow's requirements and its own fields (the view path only; the Hub
// Contacts table is ours and carries its fields already).
//
// REQUIREMENTS (must exist, written by others, never touched here): first_name, last_name, Domain,
// LinkedIn URL, Phone. FullEnrich is asked by LinkedIn URL when the row holds one, else by name +
// domain; Phone is the core cell Enrich Contacts fills, and a row that already holds a number there is
// answered from it for free. A missing requirement is named and refused on the row, before
// FullEnrich is called.
//
// OWN FIELDS (created here on first use, the Rootflow rule; never renamed or retyped):
//   Final Phone      singleLineText   the number that goes out, E.164
//   Phone Provider   singleSelect     where Final Phone came from: database (the Phone cell) or FullEnrich
//   Phone Type       singleSelect     FullEnrich's own word for the line: mobile, landline, voip, unknown
//   Phone Found At   dateTime
//   Phone Status     singleSelect     done, no_phone_found, error (error is retryable)
// A base that ran the old four-provider lane keeps its old choices (direct, toll-free, Supersoniq...);
// typecast mints the new ones beside them. The email lane's Status is not touched.
const p=$('Params').first().json;
const t=$('Resolve Table').first().json;
const have=new Set(t.fieldNames||[]);
const REQUIRED=['first_name','last_name','Domain','LinkedIn URL','Phone'];
const missing=REQUIRED.filter(n=>!have.has(n));
const OWN=[
  { name:'Final Phone', type:'singleLineText' },
  { name:'Phone Provider', type:'singleSelect', options:{ choices:[{name:'database',color:'blueLight2'},{name:'FullEnrich',color:'purpleLight2'}] } },
  { name:'Phone Type', type:'singleSelect', options:{ choices:[{name:'mobile',color:'greenLight2'},{name:'landline',color:'yellowLight2'},{name:'voip',color:'orangeLight2'},{name:'unknown',color:'grayLight2'}] } },
  { name:'Phone Found At', type:'dateTime', options:{ dateFormat:{name:'iso'}, timeFormat:{name:'24hour'}, timeZone:'utc' } },
  { name:'Phone Status', type:'singleSelect', options:{ choices:[{name:'done',color:'greenLight2'},{name:'no_phone_found',color:'grayLight2'},{name:'error',color:'redLight2'}] } }
];
const toCreate=OWN.filter(f=>!have.has(f.name));
const url='https://api.airtable.com/v0/meta/bases/'+p.base+'/tables/'+t.tableId+'/fields';
const refused=missing.length?('People ('+t.tableId+') in base '+p.base+' is missing '+missing.join(', ')+'. Enrich Phones needs them and creates only its own phone lane.'):'';
return [{ json:{ refused, missing, base:p.base, tableId:t.tableId, toCreate:toCreate.map(f=>f.name), creates:toCreate.map(f=>({ url:url, body:f })), startedAt:p.startedAt } }];

// Plan Columns: one meta-API call per own field the table lacks. Runs only when there is something
// to create; the IF before it routes an empty plan straight to the row read.
const c=$('Check Columns').first().json;
return (c.creates||[]).map(x=>({ json:x }));

// Verify Columns: the base meta read again after the creates. Every own field must now show;
// anything still missing stops the run by name before a row is read and before a provider is called.
const c=$('Check Columns').first().json;
const r=$input.first().json||{}; const body=(r.body!==undefined)?r.body:r;
const tables=(body&&Array.isArray(body.tables))?body.tables:null;
if(!tables) throw new Error('Could not re-read the table list for base '+c.base+' after creating columns: '+JSON.stringify(body).slice(0,200)+'.');
const names=new Set((((tables.find(t=>t.id===c.tableId))||{}).fields||[]).map(f=>f.name));
const still=(c.toCreate||[]).filter(n=>!names.has(n));
if(still.length) throw new Error('Enrich Phones created columns the base does not show: '+still.join(', ')+'. No provider was called.');
return [{ json:{ created:c.toCreate.slice() } }];

// Pack Rows: every row the run works, in one shape whichever table it came from, each carrying the
// run context the batch sub-execution needs (Params and Resolve Table do not exist inside a
// sub-execution). One row = one person to look up.
//   view       a People row of the client base: first_name, last_name, Domain, LinkedIn URL, Phone
//   contacts   a Hub Contacts row: firstName, lastName, domain (lookup), linkedin, phone; a contact
//              without a company domain falls back to its own email domain unless it is a freemail
const p=$('Params').first().json;
let t={}; try{ t=$('Resolve Table').first().json||{}; }catch(e){}
const contacts=p.mode==='contacts';
const s=(v)=>String(Array.isArray(v)?(v[0]==null?'':v[0]):(v==null?'':v)).trim();
const FREEMAIL=new Set(['gmail.com','yahoo.com','outlook.com','hotmail.com','icloud.com','aol.com','proton.me','protonmail.com','live.com','msn.com','gmx.com','mail.com','walla.co.il','walla.com']);
const rows=$input.all().map(i=>i.json).filter(j=>j&&j.id);
const ctx={ _mode:p.mode||'view', _baseId:p.base, _tableId:contacts?p.tableId:t.tableId, _tableName:contacts?'Contacts':(t.tableName||'People'), _view:contacts?(rows.length+' contact'+(rows.length===1?'':'s')+' named on the launch row'):(t.viewName||p.view), _execId:String($execution.id), _startedAt:p.startedAt, _clientId:p.clientRecId||'', _trigger:p.trigger||'form', _total:rows.length, _tag:p.tag||'' };
return rows.map(j=>{
  const f=j.fields||j;
  let person;
  if(contacts){
    const email=s(f.email).toLowerCase();
    let domain=s(f.domain).toLowerCase();
    if(!domain&&email.indexOf('@')>0){ const d=email.split('@')[1]; if(d&&!FREEMAIL.has(d)) domain=d; }
    person={ first:s(f.firstName), last:s(f.lastName), domain, linkedin:s(f.linkedin), held:s(f.phone) };
  } else {
    person={ first:s(f.first_name), last:s(f.last_name), domain:s(f.Domain).toLowerCase(), linkedin:s(f['LinkedIn URL']), held:s(f.Phone) };
  }
  return { json:Object.assign({ id:j.id, person }, ctx) };
});

// Build Log: the run's final row. The batches accumulated their counters in this row's Tally (each
// sub-execution reads the row, adds its slice, writes it back with Status Running); this pass reads
// the accumulated Tally once more and writes the verdict. A run with no rows writes its trace too.
//
// Status: Failed only when nothing could run (FullEnrich without a credential, refusing the key or
// out of credits on every batch, or every write refused while there was something to write). People
// FullEnrich left unanswered are errors and stay retryable; a person who could not be asked is a skip.
const p=$('Params').first().json;
let t={}; try{ t=$('Resolve Table').first().json||{}; }catch(e){}
const contacts=p.mode==='contacts';
let total=0; try{ total=$('Pack Rows').all().filter(i=>i.json&&i.json.id).length; }catch(e){}
const BLANK={ rows:0, done:0, noPhone:0, errored:0, fromDatabase:0, notAskable:0, asked:0, feFound:0, credits:0, byType:{}, written:0, writeErrors:0, writeWhy:[], unansweredWhy:[], enrichmentIds:[], batches:0, skips:{}, providerDown:false };
let a=Object.assign({},BLANK);
try{ const prior=$('Read Run Row').first().json; const pf=(prior&&prior.fields)||prior||{}; const raw=pf.Tally; if(raw){ const parsed=JSON.parse(String(raw)); if(parsed&&String(parsed.execId)===String($execution.id)) a=Object.assign({},BLANK,parsed); } }catch(e){}
const n=(v)=>Number(v)||0;
let dur=0; try{ dur=Math.max(0,Math.round(($now.toMillis()-new Date(p.startedAt).getTime())/1000)); }catch(e){}
const types=Object.entries(a.byType||{}).map(([k,v])=>k+' '+v).join(', ')||'none';
const tableName=contacts?'Contacts':(t.tableName||'People');
const tableId=contacts?p.tableId:(t.tableId||'');
const scope=contacts
  ? (p.contactIds||[]).length+' Hub contact'+((p.contactIds||[]).length===1?'':'s')+' named on the launch row, '+total+' read'
  : 'one client, People view "'+(t.viewName||p.view)+'", '+total+' rows read';
const lines=[
  '**'+n(a.rows)+' people worked, '+n(a.done)+' with a number, '+n(a.noPhone)+' no phone found, '+n(a.errored)+' unanswered**',
  '',
  '**Scope:** '+scope+(p.tag?', Tag "'+p.tag+'"':'')+', '+n(a.batches)+' batch'+(n(a.batches)===1?'':'es')+' of up to 100',
  '**Rule:** FullEnrich is the only lookup: one bulk submission per batch, phones only, asked by LinkedIn URL when the row holds one, else by name and domain. A phone cell already filled answers for free and is never sent. The view, or the contacts named, is the spend cap.',
  '',
  '**Results**',
  '- **FullEnrich:** '+n(a.asked)+' asked, '+n(a.feFound)+' found, '+n(a.credits)+' credits',
  '- **Answered from the phone cell already on the row:** '+n(a.fromDatabase),
  '- **Numbers by line type:** '+types,
  '- **Rows written (confirmed by Airtable):** '+n(a.written)+(n(a.writeErrors)?', '+n(a.writeErrors)+' refused':'')
];
if(contacts) lines.push('- On Hub contacts only a number FullEnrich found is written (phone, Phone Source); a miss writes nothing.');
if((a.enrichmentIds||[]).length) lines.push('- **FullEnrich enrichment ids:** '+a.enrichmentIds.join(', '));
const skipLines=Object.entries(a.skips||{}).map(([k,v])=>'- '+k+' ('+v+')');
if(skipLines.length) lines.push('', '**Skipped**', ...skipLines);
if(!total) lines.push('', '**Skipped ('+(contacts?'none of the named contacts could be read':'view "'+p.view+'" had no rows')+')**');
if(n(a.errored)){ lines.push('', '**Failures ('+n(a.errored)+' people unanswered, left retryable)**'); for(const w of (a.unansweredWhy||[]).slice(0,10)) lines.push('- '+w); }
if((a.writeWhy||[]).length){ lines.push('', '**Write failures**'); for(const w of a.writeWhy.slice(0,10)) lines.push('- '+w); }
const failed=n(a.errored)+n(a.writeErrors);
const nothingRan=(!!a.providerDown&&n(a.feFound)===0&&n(a.asked)>0)||(total>0&&n(a.rows)>0&&n(a.written)===0&&n(a.writeErrors)>0);
if(a.providerDown&&n(a.feFound)===0&&n(a.asked)>0) lines.push('', '**Nothing could run: FullEnrich took no submission (see Failures). Nobody was looked up and no credit was spent; the rows stay retryable.**');
const log={
  'Execution ID': String($execution.id),
  'Automation': 'Enrich Phones',
  'Status': nothingRan?'Failed':(failed?'Succeeded with errors':'Succeeded'),
  'Trigger': p.trigger||'form',
  'Errors': nothingRan?Math.max(1,failed):failed,
  'Run at': p.startedAt,
  'Target': tableName+' ('+tableId+')',
  'Records In': total,
  'Records Out': n(a.written),
  'Duration s': dur,
  'Description': lines.join('\n'),
  'Tally': JSON.stringify(Object.assign({}, a, { execId:String($execution.id) })),
  'Execution Link': 'https://n8n.flowroots.com/workflow/'+$workflow.id+'/executions/'+$execution.id
};
if(!contacts) log['View']=t.viewName||p.view;
if(p.clientRecId) log['Client']=[p.clientRecId];
return [{ json:log }];

// Prep: the batch's state and the one FullEnrich submission it makes, one item.
//
// The rule: FullEnrich is the only lookup. A person whose phone cell is already filled is answered
// from it and never sent (the view is the spend cap: feed this Rootflow a view where Phone is empty
// when a fresh lookup is what you want). Everyone else is asked once, by LinkedIn URL when the row
// holds one, else by first name + last name + domain. A person with neither cannot be asked: the row
// is marked error with the reason and costs nothing.
//
// One batch is at most 100 people, which is exactly FullEnrich's bulk maximum: one batch, one
// submission, contact.phones only (10 credits a number found, nothing for a miss). The row id rides
// in `custom` and comes back on the result, so the answer is matched by id, never by position.
const rows=$('Read Records').all().map(i=>i.json||{}).filter(j=>j.id);
const first=rows[0]||{};
const digits=(v)=>String(v||'').replace(/\D/g,'');
const plausible=(v)=>{ const d=digits(v); return d.length>=7&&d.length<=15; };
const cut=(v)=>String(v||'').slice(0,100);
const state={ mode:first._mode||'view', order:[], rows:{}, stats:{ rows:rows.length, fromDatabase:0, notAskable:0, asked:0 } };
const data=[];
for(const r of rows){
  const p=r.person||{};
  const row={ id:r.id, resolved:null, asked:false, error:'' };
  if(p.held&&plausible(p.held)){
    row.resolved={ phone:p.held, provider:'database', type:'unknown' };
    state.stats.fromDatabase++;
  } else if(p.linkedin||(p.first&&p.last&&p.domain)){
    const c={ enrich_fields:['contact.phones'], custom:{ row_id:String(r.id) } };
    if(p.first&&p.last){ c.first_name=cut(p.first); c.last_name=cut(p.last); }
    if(p.domain) c.domain=cut(p.domain);
    if(p.linkedin) c.linkedin_url=p.linkedin;
    data.push(c);
    row.asked=true;
    state.stats.asked++;
  } else {
    row.error='cannot be asked: no LinkedIn URL and no first name + last name + domain';
    state.stats.notAskable++;
  }
  state.order.push(r.id);
  state.rows[r.id]=row;
}
state._none=!data.length;
state.body={ name:'Enrich Phones '+String(first._execId||'')+' ('+(first._tableName||'People')+', '+data.length+')', data };
return [{ json:state }];

// Verdict: one write per row from the batch's state and FullEnrich's answer, the phone lane only.
//   a number (the held phone cell, or FullEnrich's most probable phone)
//        -> Final Phone (E.164), Phone Provider, Phone Type, Phone Found At, Phone Status done
//   FullEnrich finished and found nothing            -> Phone Status no_phone_found
//   the person could not be asked, the submission was refused, FullEnrich ran out of credits or the
//   45-minute cap passed before it answered            -> Phone Status error (retryable)
// The Phone cell of a People row is never written: it belongs to Enrich Contacts.
// A Hub Contacts row (a launch on named contacts) carries no phone lane: only a number FullEnrich
// found is written there, into phone and Phone Source, and a miss writes nothing.
const state=$('Prep').first().json;
// The carrier arrives on the input: from the poll loop when it settled, from Submit Check when the
// submission was refused; when nobody had to be asked the input is Prep's own item and there is none.
const inp=$input.first().json||{};
const c=(inp._t0!==undefined)?inp:{};
const now=new Date().toISOString();
const toE164=(raw)=>{ const t=String(raw||'').trim(); if(!t) return ''; const d=t.replace(/\D/g,''); if(t.charAt(0)==='+') return '+'+d; if(d.length===11&&d.charAt(0)==='1') return '+'+d; if(d.length===10&&d.charAt(0)!=='0') return '+1'+d; return t; };
const TYPES={ MOBILE:'mobile', LANDLINE:'landline', VOIP:'voip' };
const found={}; for(const x of (c.found||[])) found[x.rowId]=x;
const stopped=c.status==='FINISHED';
let why='';
if(c.submitErr) why=c.submitErr;
else if(c.status==='CREDITS_INSUFFICIENT') why='FullEnrich: out of credits mid-run';
else if(c.status==='CANCELED') why='FullEnrich: the enrichment was canceled';
else if(c.status==='UNREADABLE') why='FullEnrich: the enrichment could not be read back ('+(c.pollErr||'')+')';
else if(c.timedOut) why='FullEnrich: no answer inside the 45-minute cap (enrichment '+(c.enrichmentId||'?')+' may still finish and charge on their side)';
const contacts=state.mode==='contacts';
const st={ done:0, noPhone:0, errored:0, feFound:0, byType:{}, skips:{}, credits:Number(c.credits)||0, enrichmentIds:c.enrichmentId?[c.enrichmentId]:[], providerDown:!!c.submitErr };
const skip=(k,n)=>{ if(n) st.skips[k]=(st.skips[k]||0)+n; };
const out=[];
let unanswered=0;
for(const id of state.order){
  const r=state.rows[id];
  let hit=r.resolved||null;
  if(!hit&&r.asked){ const x=found[id]; if(x&&x.number){ hit={ phone:x.number, provider:'FullEnrich', type:TYPES[String(x.lineType).toUpperCase()]||'unknown' }; st.feFound++; } }
  if(hit){
    st.done++; st.byType[hit.type]=(st.byType[hit.type]||0)+1;
    if(contacts){ if(hit.provider==='FullEnrich') out.push({ json:{ id:id, phone:toE164(hit.phone), 'Phone Source':'FullEnrich' } }); }
    else out.push({ json:{ id:id, 'Final Phone':toE164(hit.phone), 'Phone Provider':hit.provider, 'Phone Type':hit.type, 'Phone Found At':now, 'Phone Status':'done' } });
    continue;
  }
  const answered=r.asked&&(stopped||!!found[id]);
  if(answered){ st.noPhone++; if(!contacts) out.push({ json:{ id:id, 'Phone Status':'no_phone_found' } }); continue; }
  if(r.asked){ unanswered++; st.errored++; }
  if(!contacts) out.push({ json:{ id:id, 'Phone Status':'error' } });
}
skip('Cannot be asked: no LinkedIn URL and no first name + last name + domain', state.stats.notAskable);
if(unanswered) st.unansweredWhy=why||'FullEnrich returned no answer for these people';
const stats=Object.assign({}, state.stats, st);
if(!out.length) return [{ json:{ _empty:true, _stats:stats } }];
out[0].json._stats=stats;
return out;

// Chunk Rows: the verdict rows in tens, one item per Airtable request, PATCHed as {records:[{id,
// fields}], typecast:true} 200 ms apart (typecast lets a new provider's name mint its choice on
// Phone Provider). Ids and size ride on the item for the count-back; carriers are stripped.
const rows=$input.all().map(i=>i.json).filter(j=>j&&j.id&&!j._empty);
const out=[];
for(let i=0;i<rows.length;i+=10){
  const part=rows.slice(i,i+10);
  out.push({ json:{ body:{ records:part.map(r=>{ const f={}; for(const k of Object.keys(r)){ if(k!=='id'&&k.charAt(0)!=='_') f[k]=r[k]; } return { id:String(r.id), fields:f }; }), typecast:true }, ids:part.map(r=>String(r.id)), size:part.length } });
}
return out;

// Write Check: the writer's count-back. Written rows are counted from every 2xx answer's records[];
// a request that was not 2xx counts every row it carried as a write error and names the ids. The
// writer never retries (a 429 locks the base for 30 s). Exactly one item out.
const n=(v)=>Number(v)||0;
const parse=(b)=>{ if(typeof b!=='string') return b; try{ return JSON.parse(b); }catch(e){ return null; } };
let chunks=[], resps=[];
try{ chunks=$('Chunk Rows').all().map(i=>i.json); }catch(e){}
try{ resps=$('Write Rows').all(); }catch(e){}
let written=0, writeErrors=0; const failed=[], reasons=[];
const note=(ids,why)=>{ for(const id of (ids||[])){ if(failed.length<200) failed.push(id); } const w=String(why||'').replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim().slice(0,180); if(w&&reasons.length<10) reasons.push(w); };
resps.forEach((it,i)=>{
  const c=chunks[i]||{ size:0, ids:[] }; const j=it.json||{};
  if(j.error&&j.statusCode===undefined){ writeErrors+=n(c.size); note(c.ids,'row writer: '+String((j.error&&j.error.message)||j.error||'call failed')); return; }
  const status=n(j.statusCode); const b=parse(j.body===undefined?null:j.body);
  if(status>=200&&status<300&&b&&Array.isArray(b.records)){ written+=b.records.length; if(b.records.length<n(c.size)){ const back={}; for(const r of b.records) back[String((r||{}).id||'')]=1; writeErrors+=n(c.size)-b.records.length; note((c.ids||[]).filter(id=>!back[id]),(n(c.size)-b.records.length)+' of '+c.size+' records missing from a 2xx answer'); } return; }
  const e=b&&b.error; const why=e?(typeof e==='object'?(e.message||e.type||JSON.stringify(e)):String(e)):((j.error&&j.error.message)||(typeof j.body==='string'?j.body:''));
  writeErrors+=n(c.size); note(c.ids,'HTTP '+status+' '+String(why||'')+(status===429?' (rate limited; never retried)':''));
});
return [{ json:{ written, writeErrors, writeRequests:resps.length, failed, writeReasons:reasons } }];

// Build Batch Log: this batch's slice added to the run's own Hub row. The row is the accumulator
// (static data does not survive a sub-execution): Read Log Row fetched it, the totals are added, and
// the row is written back as Running; the parent writes the verdict after the last batch.
const r=$('Read Records').first().json;
const eid=String(r._execId);
const BLANK={ rows:0, done:0, noPhone:0, errored:0, fromDatabase:0, notAskable:0, asked:0, feFound:0, credits:0, byType:{}, written:0, writeErrors:0, writeWhy:[], unansweredWhy:[], enrichmentIds:[], batches:0, skips:{}, providerDown:false };
let a=Object.assign({},BLANK);
try{ const prior=$('Read Log Row').first().json; const pf=(prior&&prior.fields)||prior||{}; const raw=pf.Tally; if(raw){ const p=JSON.parse(String(raw)); if(p&&String(p.execId)===eid) a=Object.assign({},BLANK,p); } }catch(e){}
let s={}; try{ const v=$('Verdict').first().json||{}; s=v._stats||{}; }catch(e){}
const n=(v)=>Number(v)||0;
for(const k of ['rows','done','noPhone','errored','fromDatabase','notAskable','asked','feFound','credits']) a[k]+=n(s[k]);
for(const [k,v] of Object.entries(s.byType||{})) a.byType[k]=(a.byType[k]||0)+n(v);
for(const [k,v] of Object.entries(s.skips||{})) a.skips[k]=(a.skips[k]||0)+n(v);
for(const id of (s.enrichmentIds||[])){ if(a.enrichmentIds.length<50) a.enrichmentIds.push(String(id)); }
if(s.unansweredWhy&&a.unansweredWhy.length<10&&a.unansweredWhy.indexOf(String(s.unansweredWhy))<0) a.unansweredWhy.push(String(s.unansweredWhy));
if(s.providerDown) a.providerDown=true;
try{ const wc=$('Write Check').first().json||{}; a.written+=n(wc.written); a.writeErrors+=n(wc.writeErrors); for(const w of (wc.writeReasons||[])){ if(a.writeWhy.length<10&&a.writeWhy.indexOf(String(w))<0) a.writeWhy.push(String(w)); } }catch(e){}
a.batches+=1; a.execId=eid;
const total=n(r._total);
const types=Object.entries(a.byType).map(([k,v])=>k+' '+v).join(', ')||'none';
const lines=[
  '**Running: '+a.rows+' of '+total+' people worked in '+a.batches+' batch'+(a.batches===1?'':'es')+', '+a.done+' with a number, '+a.noPhone+' no phone found, '+a.errored+' unanswered**',
  '', '**Table:** '+(r._tableName||'People')+' ('+(r._tableId||'')+') · '+(r._view||''),
  '', '- **FullEnrich:** '+a.asked+' asked, '+a.feFound+' found, '+a.credits+' credits',
  '- **Answered from the phone cell already on the row:** '+a.fromDatabase,
  '- **Numbers by line type:** '+types,
  '- **Rows written:** '+a.written+(a.writeErrors?', '+a.writeErrors+' refused':'')
];
const skipLines=Object.entries(a.skips).map(([k,v])=>'- '+k+' ('+v+')');
if(skipLines.length) lines.push('', '**Skipped**', ...skipLines);
const row={ 'Execution ID':eid, 'Automation':'Enrich Phones', 'Status':'Running', 'Trigger':r._trigger||'form', 'Run at':r._startedAt, 'Target':(r._tableName||'People')+' ('+(r._tableId||'')+')', 'Records In':total, 'Records Out':a.written, 'Errors':a.errored+a.writeErrors, 'Tally':JSON.stringify(a), 'Description':lines.join('\n'), 'Execution Link':'https://n8n.flowroots.com/workflow/'+$workflow.id+'/executions/'+eid };
if(r._mode!=='contacts') row['View']=r._view||'';
if(r._clientId) row['Client']=[r._clientId];
return [{ json:row }];

// Batch Response: the last node of the sub-execution; its output is what the parent receives.
// Counters only, never rows.
let s={}; try{ s=$('Verdict').first().json._stats||{}; }catch(e){}
let w={}; try{ w=$('Write Check').first().json||{}; }catch(e){}
return [{ json:{ done:s.done||0, noPhone:s.noPhone||0, errored:s.errored||0, credits:s.credits||0, written:w.written||0, writeErrors:w.writeErrors||0, providerDown:!!s.providerDown } }];

// Submit Check: FullEnrich's answer to the submission becomes the poll carrier: the enrichment id, or
// the reason there is none. No credential on the node, a refused key, no credits, a rate limit or a
// dead API are all a named skip on the batch, never a crash: the people it carried stay retryable.
// n8n hands a node failure over as {error}: a plain string ("Credentials not found") or an object
// with message and description. Read both shapes.
const errMsg=(e)=>{ if(!e) return 'call failed'; if(typeof e==='string') return e; return String((e.message||'')+' '+(e.description||'')).trim()||'call failed'; };
const j=$input.first().json||{};
const carrier={ enrichmentId:'', submitErr:'', status:'', polls:0, _force:false, _loop:false, _t0:Date.now() };
if(j.error&&j.body===undefined&&j.enrichment_id===undefined){
  const m=errMsg(j.error);
  carrier.submitErr=(/credential/i.test(m)?'FullEnrich: no credential on the FullEnrich nodes':'FullEnrich: '+m).slice(0,200);
  return [{ json:carrier }];
}
const code=Number(j.statusCode)||200;
let b=(j.body!==undefined)?j.body:j;
if(typeof b==='string'){ try{ b=JSON.parse(b); }catch(e){ b={ message:b }; } }
b=b||{};
if(code>=200&&code<300&&b.enrichment_id){ carrier.enrichmentId=String(b.enrichment_id); carrier.status='CREATED'; return [{ json:carrier }]; }
const why=String(b.code||'')+' '+String(b.message||'');
if(code===401||/authorization|api\.key/i.test(why)) carrier.submitErr='FullEnrich: the API key was refused (HTTP '+code+' '+why.trim()+')';
else if(code===402||/credit/i.test(why)) carrier.submitErr='FullEnrich: out of credits (HTTP '+code+' '+why.trim()+')';
else if(code===429) carrier.submitErr='FullEnrich: rate limited at submit (HTTP 429 '+why.trim()+')';
else carrier.submitErr=('FullEnrich: submit refused (HTTP '+code+' '+(why.trim()||JSON.stringify(b).slice(0,120))+')');
carrier.submitErr=carrier.submitErr.slice(0,200);
return [{ json:carrier }];

// Poll Input: the carrier of the open enrichment, re-emitted each round so FE Poll asks once and
// Poll Gate folds the answer onto it. First round from Submit Check, later rounds from the Wait.
const c=Object.assign({}, $input.first().json||{});
delete c.found;
return [{ json:c }];

// Poll Gate: one status answer folded onto the carrier. FullEnrich says CREATED or IN_PROGRESS while
// it works (or answers 400 error.enrichment.in_progress), and FINISHED, CANCELED or
// CREDITS_INSUFFICIENT when it has stopped. The loop asks every 30 seconds for up to 45 minutes; at
// the cap one last read is forced (forceResults) so whatever FullEnrich found so far is kept, and the
// people without an answer stay retryable. Only the phones ride on: the profile FullEnrich sends back
// with a LinkedIn lookup is dropped here so the batch stays small.
const MAX=45*60*1000, WAIT=30;
const c=Object.assign({}, $('Poll Input').first().json||{});
const j=$input.first().json||{};
const code=Number(j.statusCode)||0;
let b=(j.body!==undefined)?j.body:j;
if(typeof b==='string'){ try{ b=JSON.parse(b); }catch(e){ b={}; } }
b=b||{};
const elapsed=Date.now()-(Number(c._t0)||Date.now());
c.polls=(Number(c.polls)||0)+1;
const wasForced=!!c._force;
const pick=(list)=>(Array.isArray(list)?list:[]).map(d=>{
  const ci=(d&&d.contact_info)||{};
  const ph=ci.most_probable_phone||((Array.isArray(ci.phones)&&ci.phones[0])||null);
  return { rowId:String(((d&&d.custom)||{}).row_id||''), number:ph?String(ph.number||''):'', lineType:ph?String(ph.line_type||''):'', region:ph?String(ph.region||''):'' };
}).filter(x=>x.rowId);
const STOPPED=['FINISHED','CANCELED','CREDITS_INSUFFICIENT'];
let settled=false;
if(j.error&&j.body===undefined&&b.status===undefined){
  c.pollErr=String((j.error&&j.error.message)||j.error||'poll failed').slice(0,160);
} else if(code===401||code===404){
  c.pollErr='HTTP '+code+' '+String(b.code||'')+' '+String(b.message||''); c.status='UNREADABLE'; settled=true;
} else if(b.status){
  c.status=String(b.status); c.pollErr='';
  if(STOPPED.indexOf(c.status)>-1||wasForced){ c.found=pick(b.data); c.credits=Number((b.cost||{}).credits)||0; settled=true; }
} else {
  // 400 error.enrichment.in_progress, 429, or an answer without a status: still open.
  c.pollErr=(code&&code!==400)?('HTTP '+code+' '+String(b.code||'')):'';
}
if(!settled&&wasForced){ settled=true; }
if(!settled&&elapsed>=MAX){ c._force=true; }
c.timedOut=settled&&wasForced&&STOPPED.indexOf(c.status)<0;
c._loop=!settled;
c._nextWaitSec=c._force?1:WAIT;
c._elapsedS=Math.round(elapsed/1000);
return [{ json:c }];
